content:
/* GOOGLE FONTS */
@import url('https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;600&display=swap');

/* ONLY index.html background */
.home-bg {
    background-image: url('/static/bg.jpg');
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;

    height: 100vh;
    display: flex;
    justify-content: center;
    align-items: center;
}

/* Background for welcome page */
.welcome-bg {
    background-image: url('/static/farm.jpg');
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    min-height: 100vh;
    width: 100%;
}

.welcome-bg {
    display: flex;
    justify-content: center;
    align-items: center;
    flex-direction: column;
    padding: 40px 0; /* prevents cutting at top */
}


/* RESULT PAGE BACKGROUND */
.result-page {
    background: url('/static/bg.jpg') no-repeat center center/cover;
    height: 100vh;
    display: flex;
    justify-content: center;
    align-items: center;
    position: relative;
}

/* Light overlay (keeps image visible but soft) */
.result-page::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(255, 255, 255, 0.35); 
    backdrop-filter: blur(2px);
    z-index: 1;
}

/* Make glass card appear above overlay */
.result-card {
    position: relative;
    z-index: 2;
}




/* Other global body settings (DO NOT remove) */
body {
    margin: 0;
    padding: 0;
    font-family: "Poppins", sans-serif;
}

/* GLASS CARD */
.glass-card {
    width: 420px;
    padding: 35px;
    border-radius: 20px;
    background: rgba(255, 255, 255, 0.15);

    box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.20);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    border: 1px solid rgba(255, 255, 255, 0.25);
    text-align: center;
    animation: fadeIn 0.8s ease-in-out;
}

/* WELCOME PAGE BACKGROUND */
.welcome-page {
    background: url('farm.jpg') no-repeat center center/cover;
}

/* HEADINGS */
h1, h2 {
    color: white;
    font-weight: 600;
    margin-bottom: 15px;
}

/* FORM */
.form-card h2 {
    margin-bottom: 10px;
}

.input-group {
    margin-bottom: 15px;
    text-align: left;
}

.input-group label {
    color: #ffffff;
    font-weight: 500;
}

.input-group input {
    width: 100%;
    padding: 10px;
    margin-top: 6px;
    border-radius: 8px;
    border: none;
    outline: none;
    background: rgba(255,255,255,0.2);
    color: #fff;
    font-size: 14px;
}

/* BUTTONS */
.btn-primary {
    display: inline-block;
    background: #00c6ff;
    color: #fff;
    padding: 12px 25px;
    border-radius: 8px;
    text-decoration: none;
    font-weight: 600;
    transition: 0.3s;
}

.btn-primary:hover {
    background: #0099cc;
}

.btn-secondary {
    display: inline-block;
    margin-top: 12px;
    background: transparent;
    border: 2px solid #fff;
    color: white;
    padding: 10px 22px;
    border-radius: 8px;
    text-decoration: none;
    font-weight: 500;
    transition: 0.3s;
}

.btn-secondary:hover {
    background: white;
    color: #000;
}

/* RESULT */
.result-card .result {
    font-size: 36px;
    font-weight: 700;
    color: #ffe600;
    margin: 20px 0;
    text-shadow: 0 0 10px #000;
}

.actions {
    margin-top: 20px;
}

/* ANIMATION */
@keyframes fadeIn {
    from {
        opacity: 0;
        transform: translateY(20px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* Crop Image Styling */
.crop-image {
    width: 250px;
    height: 250px;
    border-radius: 15px;
    object-fit: cover;
    margin-top: 15px;
    box-shadow: 0 0 20px rgba(255, 255, 255, 0.4);
    animation: fadeIn 0.9s ease-in-out;
}

.error-box {
  background: rgba(255, 80, 80, 0.12);
  color: #990000;
  padding: 10px;
  border-radius: 6px;
  margin-bottom: 12px;
  border: 1px solid rgba(200,0,0,0.12);
}
